<?php
namespace App\Controllers;

use App\Core\Database;
use App\Helpers\AuthHelper;
use App\Helpers\NotificationHelper;
use App\Services\StockService;
use PDO;

class LoanWorkflowController extends LoanController {
    private function go(string $path): void { header('Location: '.url($path)); exit; }
    private function audit(PDO $pdo,int $uid,string $action,int $id,string $note,?array $old=null,?array $new=null): void {
        $q=$pdo->prepare("INSERT INTO audit_logs (user_id,action,entity,entity_id,old_data,new_data,ip_address,user_agent) VALUES (?,?,'loans',?,?,?,?,?)");
        $q->execute([$uid,$action,$id,$old?json_encode($old,JSON_UNESCAPED_UNICODE):null,json_encode(array_merge($new??[],['notes'=>$note]),JSON_UNESCAPED_UNICODE),$_SERVER['REMOTE_ADDR']??null,$_SERVER['HTTP_USER_AGENT']??null]);
    }
    private function csrf(string $fallback='/loans'): void { if(!hash_equals($_SESSION['csrf_token']??'',$_POST['csrf_token']??'')){$_SESSION['error']='CSRF validation gagal.';$this->go($fallback);} }
    private function bulkAvailable(PDO $pdo,int $itemId,int $warehouseId): int {
        $q=$pdo->prepare("SELECT COALESCE(s.quantity,0)-COALESCE((SELECT SUM(li.quantity-li.returned_quantity) FROM loan_items li JOIN loans l ON l.id=li.loan_id WHERE li.master_item_id=? AND l.warehouse_id=? AND l.status IN ('BORROWED','PARTIAL_RETURNED')),0) FROM stocks s WHERE s.master_item_id=? AND s.warehouse_id=?");
        $q->execute([$itemId,$warehouseId,$itemId,$warehouseId]); return max(0,(int)$q->fetchColumn());
    }
    public function index(){
        $pdo=Database::getInstance()->getConnection();$u=AuthHelper::user();$search=trim($_GET['search']??'');$status=trim($_GET['status']??'');$page=max(1,(int)($_GET['page']??1));$limit=15;$offset=($page-1)*$limit;
        $w=['1=1'];$p=[];if(!AuthHelper::hasRole(['SUPERADMIN','ADMIN'])){$w[]='l.borrower_id=?';$p[]=(int)$u['id'];}if($search!==''){$w[]='(u.name LIKE ? OR wh.name LIKE ?)';$p[]="%$search%";$p[]="%$search%";}if($status!==''){$w[]='l.status=?';$p[]=$status;}$where='WHERE '.implode(' AND ',$w);
        $c=$pdo->prepare("SELECT COUNT(*) FROM loans l JOIN users u ON u.id=l.borrower_id JOIN warehouses wh ON wh.id=l.warehouse_id $where");$c->execute($p);$totalItems=(int)$c->fetchColumn();$totalPages=max(1,(int)ceil($totalItems/$limit));
        $s=$pdo->prepare("SELECT l.*,u.name borrower_name,wh.name warehouse_name FROM loans l JOIN users u ON u.id=l.borrower_id JOIN warehouses wh ON wh.id=l.warehouse_id $where ORDER BY l.id DESC LIMIT $limit OFFSET $offset");$s->execute($p);$loans=$s->fetchAll(PDO::FETCH_ASSOC);require __DIR__.'/../../resources/views/workflow/loans/index.php';
    }
    public function create(){
        AuthHelper::requireRole(['TEKNISI_NOC']);$pdo=Database::getInstance()->getConnection();$warehouses=$pdo->query("SELECT id,name FROM warehouses WHERE is_active=1 ORDER BY name")->fetchAll(PDO::FETCH_ASSOC);$items=$pdo->query("SELECT id,nama,is_serialized FROM master_items WHERE is_active=1 ORDER BY nama")->fetchAll(PDO::FETCH_ASSOC);$s=$pdo->prepare("SELECT id FROM submissions WHERE status IN ('APPROVED','PARTIAL_APPROVED') AND submitted_by=? ORDER BY id DESC");$s->execute([AuthHelper::user()['id']]);$submissions=$s->fetchAll(PDO::FETCH_ASSOC);require __DIR__.'/../../resources/views/workflow/loans/create.php';
    }
    public function store(){
        AuthHelper::requireRole(['TEKNISI_NOC']);$this->csrf('/loans/create');$pdo=Database::getInstance()->getConnection();$uid=(int)AuthHelper::user()['id'];$wh=(int)($_POST['warehouse_id']??0);$type=$_POST['loan_type']??'INTERNAL';$sid=!empty($_POST['submission_id'])?(int)$_POST['submission_id']:null;$due=$_POST['due_date']??null;$notes=trim($_POST['notes']??'');$sources=$_POST['source_types']??[];$itemIds=$_POST['item_ids']??[];$qtys=$_POST['quantities']??[];$manual=$_POST['manual_names']??[];
        if($wh<=0){$_SESSION['error']='Gudang asal wajib dipilih.';$this->go('/loans/create');}if(!$sources){$_SESSION['error']='Tambahkan minimal satu barang.';$this->go('/loans/create');}
        try{$pdo->beginTransaction();$code=\App\Helpers\TransactionHelper::generateCode('LOAN','loans');$pdo->prepare("INSERT INTO loans(transaction_code,borrower_id,warehouse_id,submission_id,loan_type,loan_date,due_date,status,notes,processed_by) VALUES(?,?,?,?,?,NOW(),?,'PENDING_APPROVAL',?,?)")->execute([$code,$uid,$wh,$sid,$type,$due,$notes,$uid]);$loanId=(int)$pdo->lastInsertId();$si=$pdo->prepare("INSERT INTO loan_items(loan_id,master_item_id,requested_quantity,approved_quantity,quantity,returned_quantity) VALUES(?,?,?,0,0,0)");$mi=$pdo->prepare("INSERT INTO loan_manual_items(loan_id,name,requested_quantity,approved_quantity,quantity,returned_quantity,specification,unit) VALUES(?,?,?,0,0,0,NULL,NULL)");$lines=0;
            foreach($sources as $i=>$src){$qty=(int)($qtys[$i]??0);if($qty<1)continue;if($src==='MANUAL'){$name=trim($manual[$i]??'');if($name==='')throw new \Exception('Nama barang manual wajib diisi.');$mi->execute([$loanId,$name,$qty]);$lines++;continue;}$itemId=(int)($itemIds[$i]??0);$q=$pdo->prepare("SELECT id,nama,is_serialized FROM master_items WHERE id=? AND is_active=1");$q->execute([$itemId]);$item=$q->fetch(PDO::FETCH_ASSOC);if(!$item)throw new \Exception('Barang dari stok tidak valid.');$available=(int)$item['is_serialized']?(int)$pdo->query("SELECT COUNT(*) FROM serial_numbers WHERE master_item_id=".$itemId." AND current_warehouse_id=".$wh." AND status='AVAILABLE'")->fetchColumn():$this->bulkAvailable($pdo,$itemId,$wh);if($available<$qty)throw new \Exception("Barang {$item['nama']} yang tersedia untuk dipinjam hanya $available.");$si->execute([$loanId,$itemId,$qty]);$lines++;}
            if($lines===0)throw new \Exception('Tidak ada barang valid.');$this->audit($pdo,$uid,'CREATE',$loanId,'Peminjaman diajukan. Belum mengurangi stok dan menunggu keputusan Admin.',null,['status'=>'PENDING_APPROVAL']);$pdo->commit();NotificationHelper::createForRoleOnce('ADMIN','Peminjaman Baru Menunggu Persetujuan',AuthHelper::user()['name'].' mengajukan peminjaman baru.','info','/loans/show?id='.$loanId);$_SESSION['success']='Peminjaman berhasil diajukan dan menunggu persetujuan Admin.';
        }catch(\Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$_SESSION['error']='Gagal mengajukan peminjaman: '.$e->getMessage();}$this->go('/loans');
    }
    public function approve(){
        AuthHelper::requireRole(['ADMIN']);AuthHelper::denySuperadminWrite();$this->csrf('/loans');$pdo=Database::getInstance()->getConnection();$uid=(int)AuthHelper::user()['id'];$id=(int)($_POST['id']??0);$inc=$_POST['approved_include']??[];$qty=$_POST['approved_qty']??[];$mqty=$_POST['approved_manual_qty']??[];$sns=$_POST['approved_serials']??[];$note=trim($_POST['approval_notes']??'');
        try{$pdo->beginTransaction();$q=$pdo->prepare("SELECT * FROM loans WHERE id=? FOR UPDATE");$q->execute([$id]);$loan=$q->fetch(PDO::FETCH_ASSOC);if(!$loan||$loan['status']!=='PENDING_APPROVAL')throw new \Exception('Peminjaman sudah diproses.');$lines=0;
            $q=$pdo->prepare("SELECT li.*,m.nama,m.is_serialized FROM loan_items li JOIN master_items m ON m.id=li.master_item_id WHERE li.loan_id=? ORDER BY li.id");$q->execute([$id]);foreach($q->fetchAll(PDO::FETCH_ASSOC) as $it){$lid=(int)$it['id'];$requested=(int)$it['requested_quantity'];if(!isset($inc[$lid])){$pdo->prepare("UPDATE loan_items SET approved_quantity=0,quantity=0 WHERE id=?")->execute([$lid]);continue;}$approved=min($requested,max(0,(int)($qty[$lid]??0)));if($approved<1)continue;$available=(int)$it['is_serialized']?(int)$pdo->query("SELECT COUNT(*) FROM serial_numbers WHERE master_item_id=".(int)$it['master_item_id']." AND current_warehouse_id=".(int)$loan['warehouse_id']." AND status='AVAILABLE'")->fetchColumn():$this->bulkAvailable($pdo,(int)$it['master_item_id'],(int)$loan['warehouse_id']);if($available<$approved)throw new \Exception("Barang {$it['nama']} yang tersedia hanya $available.");$pdo->prepare("UPDATE loan_items SET approved_quantity=?,quantity=? WHERE id=?")->execute([$approved,$approved,$lid]);$lines++;if((int)$it['is_serialized']===1){$selected=array_values(array_filter(array_map('intval',(array)($sns[$lid]??[]))));if(count($selected)!==$approved)throw new \Exception("Pilih tepat $approved nomor seri untuk {$it['nama']}.");$del=$pdo->prepare("DELETE FROM loan_item_serials WHERE loan_item_id=? AND status='PENDING'");$del->execute([$lid]);$ins=$pdo->prepare("INSERT INTO loan_item_serials(loan_item_id,serial_number_id,status) VALUES(?,?, 'PENDING')");foreach($selected as $snId){$v=$pdo->prepare("SELECT id FROM serial_numbers WHERE id=? AND master_item_id=? AND current_warehouse_id=? AND status='AVAILABLE' FOR UPDATE");$v->execute([$snId,$it['master_item_id'],$loan['warehouse_id']]);if(!$v->fetchColumn())throw new \Exception('Nomor seri yang dipilih sudah tidak tersedia.');$ins->execute([$lid,$snId]);}}}
            $q=$pdo->prepare("SELECT * FROM loan_manual_items WHERE loan_id=? ORDER BY id");$q->execute([$id]);foreach($q->fetchAll(PDO::FETCH_ASSOC) as $it){$mid=(int)$it['id'];if(!isset($inc['m'.$mid])){$pdo->prepare("UPDATE loan_manual_items SET approved_quantity=0,quantity=0 WHERE id=?")->execute([$mid]);continue;}$approved=min((int)$it['requested_quantity'],max(0,(int)($mqty[$mid]??0)));if($approved<1)continue;$pdo->prepare("UPDATE loan_manual_items SET approved_quantity=?,quantity=? WHERE id=?")->execute([$approved,$approved,$mid]);$lines++;}
            if($lines===0)throw new \Exception('Minimal satu barang harus disetujui.');$pdo->prepare("UPDATE loans SET status='APPROVED',approved_by=?,approved_at=NOW(),approval_notes=?,processed_by=? WHERE id=?")->execute([$uid,$note!==''?$note:null,$uid,$id]);$this->audit($pdo,$uid,'APPROVE',$id,$note!==''?$note:'Peminjaman disetujui setelah Admin menentukan barang dan jumlah.', ['status'=>'PENDING_APPROVAL'], ['status'=>'APPROVED']);$pdo->commit();NotificationHelper::createForUsers([(int)$loan['borrower_id']],'Peminjaman Disetujui','Peminjaman Anda disetujui dan menunggu serah terima.','success','/loans/show?id='.$id);$_SESSION['success']='Peminjaman disetujui sesuai keputusan Admin.';
        }catch(\Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$_SESSION['error']='Gagal menyetujui: '.$e->getMessage();}$this->go('/loans/show?id='.$id);
    }
    public function reject(){
        AuthHelper::requireRole(['ADMIN']);AuthHelper::denySuperadminWrite();$this->csrf('/loans');$pdo=Database::getInstance()->getConnection();$uid=(int)AuthHelper::user()['id'];$id=(int)($_POST['id']??0);$reason=trim($_POST['approval_notes']??'');if($reason===''){$_SESSION['error']='Alasan penolakan wajib diisi.';$this->go('/loans/show?id='.$id);}try{$pdo->beginTransaction();$q=$pdo->prepare("SELECT borrower_id,status FROM loans WHERE id=? FOR UPDATE");$q->execute([$id]);$loan=$q->fetch(PDO::FETCH_ASSOC);if(!$loan||$loan['status']!=='PENDING_APPROVAL')throw new \Exception('Peminjaman sudah diproses.');$pdo->prepare("UPDATE loans SET status='REJECTED',approved_by=?,approved_at=NOW(),approval_notes=?,processed_by=? WHERE id=?")->execute([$uid,$reason,$uid,$id]);$this->audit($pdo,$uid,'REJECT',$id,$reason,['status'=>'PENDING_APPROVAL'],['status'=>'REJECTED']);$pdo->commit();NotificationHelper::createForUsers([(int)$loan['borrower_id']],'Peminjaman Ditolak','Peminjaman Anda ditolak.','danger','/loans/show?id='.$id);$_SESSION['success']='Peminjaman ditolak.';}catch(\Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$_SESSION['error']='Gagal menolak: '.$e->getMessage();}$this->go('/loans/show?id='.$id);
    }
    public function handover(){
        AuthHelper::requireRole(['ADMIN']);AuthHelper::denySuperadminWrite();$this->csrf('/loans');$pdo=Database::getInstance()->getConnection();$uid=(int)AuthHelper::user()['id'];$id=(int)($_POST['id']??0);$svc=new StockService();
        try{$pdo->beginTransaction();$q=$pdo->prepare("SELECT * FROM loans WHERE id=? FOR UPDATE");$q->execute([$id]);$loan=$q->fetch(PDO::FETCH_ASSOC);if(!$loan||$loan['status']!=='APPROVED')throw new \Exception('Peminjaman belum siap diserahkan.');$q=$pdo->prepare("SELECT li.*,m.nama,m.is_serialized FROM loan_items li JOIN master_items m ON m.id=li.master_item_id WHERE li.loan_id=? AND li.quantity>0 ORDER BY li.id");$q->execute([$id]);foreach($q->fetchAll(PDO::FETCH_ASSOC) as $it){$qty=(int)$it['quantity'];$available=(int)$it['is_serialized']?(int)$pdo->query("SELECT COUNT(*) FROM serial_numbers WHERE master_item_id=".(int)$it['master_item_id']." AND current_warehouse_id=".(int)$loan['warehouse_id']." AND status='AVAILABLE'")->fetchColumn():$this->bulkAvailable($pdo,(int)$it['master_item_id'],(int)$loan['warehouse_id']);if($available<$qty)throw new \Exception("Barang {$it['nama']} berubah dan tidak mencukupi.");if((int)$it['is_serialized']===1){$sn=$pdo->prepare("SELECT serial_number_id FROM loan_item_serials WHERE loan_item_id=? AND status='PENDING' FOR UPDATE");$sn->execute([$it['id']]);$rows=$sn->fetchAll(PDO::FETCH_COLUMN);if(count($rows)!==$qty)throw new \Exception("Nomor seri {$it['nama']} belum lengkap.");foreach($rows as $snId){$svc->moveSerial((int)$snId,'LOANED',null,null,(int)$loan['borrower_id'],'loan',$id,'Serah terima peminjaman.');$pdo->prepare("UPDATE loan_item_serials SET status='BORROWED' WHERE loan_item_id=? AND serial_number_id=?")->execute([$it['id'],$snId]);}}}
            $pdo->prepare("UPDATE loans SET status='BORROWED',handed_over_by=?,handed_over_at=NOW(),processed_by=? WHERE id=?")->execute([$uid,$uid,$id]);$this->audit($pdo,$uid,'HANDOVER',$id,'Barang diserahkan. Stok fisik tetap, barang tercatat sebagai dipinjam.',['status'=>'APPROVED'],['status'=>'BORROWED']);$pdo->commit();NotificationHelper::createForUsers([(int)$loan['borrower_id']],'Barang Peminjaman Diserahkan','Barang sudah diserahkan dan sekarang berada dalam penguasaan Anda.','success','/loans/show?id='.$id);$_SESSION['success']='Serah terima berhasil. Stok fisik tidak berkurang.';
        }catch(\Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$_SESSION['error']='Gagal serah terima: '.$e->getMessage();}$this->go('/loans/show?id='.$id);
    }
    public function show(){
        $id=(int)($_GET['id']??0);$pdo=Database::getInstance()->getConnection();$u=AuthHelper::user();$q=$pdo->prepare("SELECT l.*,w.name warehouse_name,u.name borrower_name FROM loans l JOIN warehouses w ON w.id=l.warehouse_id JOIN users u ON u.id=l.borrower_id WHERE l.id=?");$q->execute([$id]);$loan=$q->fetch(PDO::FETCH_ASSOC);if(!$loan){$_SESSION['error']='Peminjaman tidak ditemukan.';$this->go('/loans');}if($u['role']==='TEKNISI_NOC'&&(int)$loan['borrower_id']!==(int)$u['id'])$this->go('/loans');
        $items=[];$q=$pdo->prepare("SELECT li.id,li.master_item_id,li.requested_quantity,li.approved_quantity,li.quantity,li.returned_quantity,m.nama,m.is_serialized,'STOCK' source_type FROM loan_items li JOIN master_items m ON m.id=li.master_item_id WHERE li.loan_id=? ORDER BY li.id");$q->execute([$id]);foreach($q->fetchAll(PDO::FETCH_ASSOC) as $r)$items[]=$r;$q=$pdo->prepare("SELECT id,name nama,requested_quantity,approved_quantity,quantity,returned_quantity,specification,unit,'MANUAL' source_type FROM loan_manual_items WHERE loan_id=? ORDER BY id");$q->execute([$id]);foreach($q->fetchAll(PDO::FETCH_ASSOC) as $r){$r['is_serialized']=0;$items[]=$r;}
        $snQ=$pdo->prepare("SELECT sn.serial_number,lis.status FROM loan_item_serials lis JOIN serial_numbers sn ON sn.id=lis.serial_number_id WHERE lis.loan_item_id=? ORDER BY sn.serial_number");foreach($items as &$it){$it['serial_numbers']=[];if(($it['source_type']??'')==='STOCK'&&(int)$it['is_serialized']===1){$snQ->execute([(int)$it['id']]);$it['serial_numbers']=$snQ->fetchAll(PDO::FETCH_ASSOC);}}unset($it);
        $availableSerials=[];if($loan['status']==='PENDING_APPROVAL'&&AuthHelper::hasRole(['ADMIN'])){foreach($items as $it){if(($it['source_type']??'')==='STOCK'&&(int)$it['is_serialized']===1){$q=$pdo->prepare("SELECT id,serial_number FROM serial_numbers WHERE master_item_id=? AND current_warehouse_id=? AND status='AVAILABLE' ORDER BY serial_number");$q->execute([(int)$it['master_item_id'],(int)$loan['warehouse_id']]);$availableSerials[(int)$it['id']]=$q->fetchAll(PDO::FETCH_ASSOC);}}}
        $q=$pdo->prepare("SELECT a.*,u.name user_name FROM audit_logs a LEFT JOIN users u ON u.id=a.user_id WHERE a.entity='loans' AND a.entity_id=? ORDER BY a.created_at DESC,a.id DESC");$q->execute([$id]);$timeline=$q->fetchAll(PDO::FETCH_ASSOC);require __DIR__.'/../../resources/views/workflow/loans/show.php';
    }
}
